def prepare():
    prose = [CONTEXTS] + [q["instructions"] for q in QUESTIONS.values()] + [v for q in QUESTIONS.values() for v in q["criteria"].values()]
    for variants in prose:
        assert len(variants) == len(set(variants)) == 3
    for i in range(3):
        request = {"model": "jev-latest", "state": CONTEXTS[i], "questions": {name: {"type": "choice", "instructions": q["instructions"][i], "criteria": {key: variants[i] for key, variants in q["criteria"].items()}} for name, q in QUESTIONS.items()}}
        (OUT / f"request-{i+1}.json").write_text(json.dumps(request, indent=2) + "\n")
    audit = {
        "status": "reviewed before send",
        "method": "Manual semantic comparison of every context, question and alternative, plus full-string inequality for all explanatory fields. Stable technical names/facts preserved; no response appears in any later request.",
        "equivalent_fact_groups": ["source/design only", "AI author/full Can/no host harness", "R/C/N and current backend", "bounded disk/load/pre-effect cleanup/no persistent bundles", "exact hostile native values/identity/late behavior", "closed catalogue and async callable versus specialized sync helpers", "opaque transport and manifest/realm separation", "immediate descriptors versus unqualified C ingress", "browser corruption/replay/callback facts and proposed token/seal gaps", "same-task DOM, pending input, clone/event order/page Fetch/Can codec bindings and shared Firefox", "SQL hard cases/engines/writer counts and adapter-limited independence", "connection identity/exact errors/ambiguous commit", "SQL source versus stale comments and proposed stronger sentinel oracle", "native settlement/fence before independent read and cold-pool requalification", "namespace cleanup flaws", "hostile candidate launcher input versus sanitized direct entry/fd3/fd4", "per-obligation retirement proof"],
        "stable_question_alternatives": {key: list(q["criteria"]) for key, q in QUESTIONS.items()},
        "limitations": "Agreement is advice; it does not establish feasibility, coverage equivalence, complete bias removal or working cleanup."
    }
    (OUT / "wording-audit.json").write_text(json.dumps(audit, indent=2) + "\n")

if "--send" not in sys.argv:
    prepare()
    print("Prepared three fresh requests and pre-send audit.")
else:
    for i in range(1, 4):
        if (OUT / f"response-{i}.json").exists():
            raise SystemExit("Refusing to overwrite a saved response.")
        started = datetime.datetime.now(datetime.timezone.utc).isoformat()
        request = urllib.request.Request("https://api.typesafe.ai/v1/systemone", data=(OUT / f"request-{i}.json").read_bytes(), headers={"Content-Type": "application/json", "Authorization": "Bearer " + os.environ["TYPESAFE_API_KEY"]})
        try:
            with urllib.request.urlopen(request, timeout=55) as response:
                body, status = response.read(), response.status
        except urllib.error.URLError as error:
            (OUT / f"transport-error-{i}.json").write_text(json.dumps({"started_utc": started, "kind": type(error).__name__, "reason": str(error.reason)}, indent=2) + "\n")
            raise SystemExit("Consultation transport failed; metadata saved.")
        (OUT / f"response-{i}.json").write_bytes(body + b"\n")
        (OUT / f"response-{i}.metadata.json").write_text(json.dumps({"started_utc": started, "http_status": status}, indent=2) + "\n")
        parsed = json.loads(body)
        print(json.dumps({"request": i, "model": parsed.get("model"), "answers": parsed.get("answers"), "usage": parsed.get("usage")}), flush=True)
